using GrowthModels
using Test
using CSV, Tables
using SparseArrays, LinearAlgebra

# This fixture was generated by Kaplan–Moll's original RBC script:
# https://benjaminmoll.com/wp-content/uploads/2020/06/HJB_diffusion_implicit_RBC.m
# That script differences the productivity drift forward even when it is
# negative. Preserve the historical comparison using an explicit test-only
# stencil; the production solver now uses monotone sign-dependent upwinding.
function solve_with_legacy_rbc_stencil(m, hp, state)
    z = state[:z]
    dz = z[2] - z[1]
    process = m.stochasticprocess
    μ = (-process.θ .* log.(z) .+ process.σ^2 / 2) .* z
    variance = process.σ^2 .* z.^2
    lower = variance ./ (2 * dz^2)
    upper = μ ./ dz .+ lower
    diagonal = .-(lower .+ upper)
    diagonal[1] += lower[1]
    diagonal[end] += upper[end]
    Q = spdiagm(-1 => lower[2:end], 0 => diagonal, 1 => upper[1:end-1])
    B = kron(Q, sparse(I, hp[:k].N, hp[:k].N))
    value = Value(state)
    value.v[:] = GrowthModels.initial_guess(m, state)
    for n in 1:1000
        output = update_v(m, value, state, hp, B; iter = n, verbose = false)
        value = output[1]
        if value.convergence_status
            return (value = value, variables = output[3])
        end
    end
    error("Legacy RBC benchmark did not converge")
end

@testset "RBC diffusion: historical fixture and corrected residual" begin
    variance = 0.07
    zmean = exp(variance / 2)
    k_st = (0.3 * zmean / (0.05 + 0.05))^(1 / (1 - 0.3))
    process = from_stationary_OrnsteinUhlenbeckProcess(ρ = 0.9, ln_stationary_μ = zmean)
    m = StochasticRamseyCassKoopmansModel(process;
        γ = 2.0, A = 1.0, ρ = 0.05, α = 0.3, δ = 0.05)
    hp = StateSpaceHyperParams((
        k = HyperParams(N = 10, xmin = 0.3 * k_st, xmax = 3 * k_st),
        z = HyperParams(N = 4, xmin = 0.8 * zmean, xmax = 1.2 * zmean)))
    state = StateSpace(m, hp)

    legacy = solve_with_legacy_rbc_stencil(m, hp, state)
    legacy_savings = legacy.variables.y .- m.δ .* legacy.variables.k .- legacy.variables.c
    fixture = Tables.matrix(CSV.File(
        joinpath(@__DIR__, "test-data", "diffusion-rbc-matlab-output.csv"); header = false))
    @test maximum(abs.(legacy_savings .- fixture)) < 1e-6

    corrected = solve_HJB(m, hp; verbose = false)
    @test corrected.value.convergence_status
    utility = corrected.variables.c.^(1 - m.γ) ./ (1 - m.γ)
    residual = vec(utility) + corrected.value.A * vec(corrected.value.v) - m.ρ * vec(corrected.value.v)
    @test norm(residual, Inf) < 1e-6
    @test GrowthModels.check_generator(corrected.value.A) === nothing
    corrected_savings = corrected.variables.y .- m.δ .* corrected.variables.k .- corrected.variables.c
    # The new stencil changes the coarse-grid result; do not silently restore
    # the old discretization merely to reproduce the historical CSV.
    @test maximum(abs.(corrected_savings .- legacy_savings)) > 1e-3
end
